// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/risk/matrices", wrapper.RiskListMatrices)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/risk/matrices", wrapper.RiskCreateMatrix)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/admin/v1/risk/matrices/{id}", wrapper.RiskDeleteMatrix)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/risk/matrices/{id}", wrapper.RiskGetMatrix)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/admin/v1/risk/matrices/{id}", wrapper.RiskUpdateMatrix)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/ropa/activities/{id}/risk-score", wrapper.RiskGetLatestActivityScore)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/ropa/activities/{id}/risk-score", wrapper.RiskScoreActivity)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/risk/gap-rules", wrapper.RiskListGapRules)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/risk/gap-findings", wrapper.RiskListOpenGapFindings)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/ropa/activities/{id}/gap-findings", wrapper.RiskListActivityGapFindings)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/ropa/activities/{id}/gap-analysis", wrapper.RiskAnalyzeActivity)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/risk/gap-findings/{id}/remediate", wrapper.RiskRemediateGapFinding)
	})

	return r
}

